@push('scripts')<script>
document.addEventListener('DOMContentLoaded',()=>{const services={{ Illuminate\Support\Js::from($services->mapWithKeys(fn($s)=>[(string)$s->id=>['gu'=>$s->name_gu,'en'=>$s->name_en,'fee'=>(float)$s->service_fee,'gst'=>(float)$s->gst_rate,'government'=>(float)($s->activeGovernmentChargeItems->sum('amount') ?: $s->government_charges),'property'=>(bool)$s->requires_property_documents,'days'=>$s->estimated_days,'docs'=>$s->activeRequiredDocuments->map(fn($d)=>['gu'=>$d->name_gu,'en'=>$d->name_en,'type'=>$d->requirement_type])->values()]])) }};const safe=value=>{const node=document.createElement('span');node.textContent=String(value??'');return node.innerHTML};let step=1;const panels=[...document.querySelectorAll('[data-step]')],steps=[...document.querySelectorAll('.request-step')],checks=[...document.querySelectorAll('.service-choice-input')],money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(v),selected=()=>checks.filter(c=>c.checked).map(c=>services[c.value]);function render(){panels.forEach(p=>p.classList.toggle('d-none',+p.dataset.step!==step));steps.forEach((s,i)=>s.classList.toggle('active',i+1===step));document.getElementById('previous-step').classList.toggle('d-none',step===1);document.getElementById('next-step').classList.toggle('d-none',step===4);document.getElementById('submit-request').classList.toggle('d-none',step!==4);if(step===4)review()}function totals(){const items=selected(),professional=items.reduce((t,s)=>t+s.fee,0),gst=items.reduce((t,s)=>t+s.fee*s.gst/100,0),government=items.reduce((t,s)=>t+s.government,0);document.getElementById('professional-total').textContent=money(professional);document.getElementById('gst-total').textContent=money(gst);document.getElementById('government-total').textContent=money(government);document.getElementById('grand-total').textContent=money(professional+gst+government);const required=new Map,anyOneRequired=new Map,optional=new Map;items.flatMap(s=>s.docs).forEach(d=>({required,any_one_required:anyOneRequired,optional}[d.type]??optional).set(d.en,d));[['required-documents',required,'Required'],['any-one-required-documents',anyOneRequired,'Any One Required'],['optional-documents',optional,'Optional']].forEach(([id,map,label])=>{const list=document.getElementById(id);list.replaceChildren();map.forEach(d=>{const li=document.createElement('li');li.innerHTML=`<span>${safe(d.gu)}<small class="d-block text-muted">${safe(d.en)}</small></span><span class="badge ${label==='Required'?'text-bg-danger':label==='Any One Required'?'text-bg-warning':'text-bg-secondary'} align-self-center">${label}</span>`;list.append(li)});if(!map.size)list.innerHTML='<li class="text-muted">None configured</li>'})}function review(){const items=selected(),files=[...document.getElementById('documents').files],days=Math.max(0,...items.map(s=>s.days||0)),propertyCard=items.some(s=>s.property)?`<div class="col-md-6"><div class="review-card"><h3>Property Details</h3><div>${safe(document.getElementById('property_village').value)}, ${safe(document.getElementById('property_taluka').value)}, ${safe(document.getElementById('property_district').value)}</div></div></div>`:'';document.getElementById('request-review').innerHTML=`<div class="col-md-6"><div class="review-card"><h3>Customer Information</h3><strong>${safe(document.getElementById('name').value)}</strong><div>${safe(document.getElementById('mobile').value)}</div></div></div>${propertyCard}<div class="col-md-6"><div class="review-card"><h3>Selected Services</h3><ul>${items.map(s=>`<li>${safe(s.gu)} / ${safe(s.en)}</li>`).join('')}</ul><div>Estimated: ${days||'After review'} day(s)</div></div></div><div class="col-md-6"><div class="review-card"><h3>Fee Summary</h3><div>${document.getElementById('professional-total').textContent} Professional</div><div>${document.getElementById('gst-total').textContent} GST Extra</div><div>${document.getElementById('government-total').textContent} Government</div><strong>${document.getElementById('grand-total').textContent}</strong></div></div><div class="col-md-6"><div class="review-card"><h3>Documents Selected</h3>${files.length?`<ul>${files.map(f=>`<li>${safe(f.name)}</li>`).join('')}</ul>`:'No documents selected'}</div></div>`}const propertyInputs=['property_village','property_taluka','property_district'].map(id=>document.getElementById(id));function propertyRules(){const required=selected().some(s=>s.property);document.getElementById('property-details-section').classList.toggle('d-none',!required);propertyInputs.forEach(input=>input.required=required)}checks.forEach(c=>c.addEventListener('change',()=>{totals();propertyRules()}));propertyRules();document.getElementById('next-step').addEventListener('click',()=>{if(step===1){const invalid=panels[0].querySelector(':invalid');if(invalid){invalid.reportValidity();return}}if(step===2&&!selected().length){alert('Please select at least one service.');return}step++;render()});document.getElementById('previous-step').addEventListener('click',()=>{step--;render()});const input=document.getElementById('documents'),list=document.getElementById('selected-file-list');input.addEventListener('change',()=>{const files=[...input.files],seen=new Set;list.replaceChildren();let duplicate=false;files.forEach(f=>{const key=`${safe(f.name)}|${f.size}|${f.lastModified}`;if(seen.has(key))duplicate=true;seen.add(key);const li=document.createElement('li');li.className='list-group-item d-flex justify-content-between';li.innerHTML=`<span>${safe(f.name)}</span><small>${(f.size/1048576).toFixed(2)} MB</small>`;list.append(li)});input.setCustomValidity(duplicate?'Duplicate files are not allowed.':'');document.getElementById('upload-progress').classList.toggle('d-none',!files.length);document.querySelector('#upload-progress .progress-bar').style.width=`${Math.min(100,files.length*10)}%`});document.getElementById('final-request-form').addEventListener('submit',()=>{const b=document.getElementById('submit-request');b.disabled=true;b.textContent='Submitting securely...'});totals();render()});
</script>@endpush
